        activity: {
          id: 'international-clients-43-scenario-1',
          kind: 'scenario',
          title: "'Money is not a problem'",
          prompt: 'Choose the best response.',
          concept: 'listening to what is not said',
          situation: "Early in a call, a founder in Toronto (a fictional example) says: 'Money is not a problem for us. We just want it to be great.' You do not yet know what the job is.",
          options: [
            { text: "'Thank you, that helps. So I can suggest the right amount of work, what would a great result change for the business, and is there a range you have in mind?'", consequence: "He describes what great means for his customers and, when asked gently, gives a range. You now know the goal and the limit, and you can build a proposal that fits.", quality: 'best' },
            { text: "'Wonderful. I will plan my most complete option and send a proposal tomorrow.'", consequence: "You may be right, but you guessed what great means. The proposal misses what he cares about and he asks for changes.", quality: 'acceptable' },
            { text: "'Great, then my price will be higher, since you can afford it.'", consequence: "He feels judged and a little tricked. The sentence 'money is not a problem' was an opening, and you used it against him.", quality: 'poor' },
            { text: "'Everyone says that. What is your exact budget in numbers?'", consequence: "He feels doubted. He says he will think about it, and the call cools down.", quality: 'poor' },
          ],
          hints: [
            "'Money is not a problem' is a statement, not a fact about the job. Find out what is behind 'great'.",
            'Look for the option that thanks him, asks about the result and stays open about the range.',
            'The best answer is curious and respectful, and it does not guess or push.',
          ],
          explanation: "A client who says money is not a problem has told you the limit may be flexible, but not what the work is for. The best reply asks what a great result changes and invites a range. Guessing, pricing up because he can afford it, or doubting him each costs trust.",
        },
